query:
mutation networkConfigDnsUpdateServerSet ( $accountId:ID! $networkConfigDnsUpdateServerSetInput:NetworkConfigDnsUpdateServerSetInput!) {
	networkConfig ( accountId:$accountId ) {
		dns {
			updateServerSet ( input:$networkConfigDnsUpdateServerSetInput   ) {
				dnsServerSet {
					id
					name
					server
					audit {
						updatedTime
						updatedBy {
							id
							name
						}
					}
				}
			}
		}
	}	
}
